using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI ---
var openAiClient = new OpenAI.OpenAIClient(apiKey);
IChatClient chatClient = new OpenAIChatClient(openAiClient.GetChatClient(modelId));

// --- Define tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch.SearchAsync),
    AIFunctionFactory.Create(Notebook.AddNote),
    AIFunctionFactory.Create(Notebook.GetNotes),
};

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic, you must:
        1. Search the web for relevant information using the search tool.
        2. Take notes on key findings using the note-taking tool.
        3. Repeat steps 1-2 with refined queries to build a comprehensive view.
        4. Retrieve all your notes, then produce a well-structured summary with
           key facts, different perspectives, and source attributions.
        Always search at least twice with different queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches a topic by searching the web and taking notes.",
    tools: tools);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions))
{
    if (update.Text is { Length: > 0 } text)
    {
        Console.Write(text);
    }
}

Console.WriteLine();

// --- Tool implementations ---

/// <summary>Simulated web search tool.</summary>
static class WebSearch
{
    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public static Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        // In production, wire this to Bing Search API, Google Custom Search, etc.
        var results = new[]
        {
            new { Title = $"Overview of {query}", Snippet = $"Comprehensive overview covering the main aspects of {query}. This topic encompasses several key areas of study and practice.", Source = "encyclopedia.example.com" },
            new { Title = $"Recent developments in {query}", Snippet = $"Recent research has shown significant advances in {query}, including new methodologies and frameworks that have emerged in the past year.", Source = "news.example.com" },
            new { Title = $"{query} - Expert Analysis", Snippet = $"Experts suggest that {query} will continue to evolve rapidly. Key challenges include scalability, adoption, and integration with existing systems.", Source = "analysis.example.com" },
        };

        Console.WriteLine($"  [Tool] Web search: \"{query}\"");

        return Task.FromResult(JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
    }
}

/// <summary>Note-taking tool for the agent to record findings.</summary>
static class Notebook
{
    private static readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record key findings during research.")]
    public static string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        }

        Console.WriteLine($"  [Tool] Retrieved {_notes.Count} note(s)");
        return sb.ToString();
    }
}

